+using UnityEngine;
+using GameForge.Core;
+
+namespace GameForge.Player
+{
+    public class DashComponent : MonoBehaviour, IDashable
+    {
+        [SerializeField] private DashData dashData;
+        
+        private float lastDashTime = -999f;
+        private bool isDashing;
+
+        public bool IsDashing => isDashing;
+        public bool CanDash => Time.time >= lastDashTime + dashData.CooldownDuration;
+
+        public void Dash()
+        {
+            if (!CanDash) return;
+
+            StartCoroutine(DashRoutine());
+        }
+
+        private System.Collections.IEnumerator DashRoutine()
+        {
+            isDashing = true;
+            lastDashTime = Time.time;
+
+            yield return new WaitForSeconds(dashData.InvincibilityDuration);
+
+            isDashing = false;
+        }
+    }
+}

