+using UnityEngine;
+using GameForge.Core;
+
+namespace GameForge.Player
+{
+    [RequireComponent(typeof(DashComponent), typeof(HealthComponent))]
+    public class PlayerController : MonoBehaviour
+    {
+        private DashComponent dashComponent;
+        private HealthComponent healthComponent;
+
+        public DashComponent Dash => dashComponent;
+        public HealthComponent Health => healthComponent;
+
+        private void Awake()
+        {
+            dashComponent = GetComponent<DashComponent>();
+            healthComponent = GetComponent<HealthComponent>();
+        }
+
+        private void Update()
+        {
+            HandleInput();
+        }
+
+        private void HandleInput()
+        {
+            if (Input.GetKeyDown(KeyCode.Space))
+            {
+                if (dashComponent != null && dashComponent.CanDash)
+                {
+                    dashComponent.Dash();
+                }
+            }
+        }
+    }
+}

