+using System.Collections.Generic;
+using UnityEngine;
+using GameForge.Player;
+
+namespace GameForge.Build
+{
+    public class BuildManager : MonoBehaviour
+    {
+        [SerializeField] private List<ItemData> availableItems = new List<ItemData>();
+        [SerializeField] private PlayerController playerController;
+
+        private List<ItemData> currentSelection = new List<ItemData>();
+
+        public List<ItemData> GenerateItemChoices(int count = 3)
+        {
+            currentSelection.Clear();
+            if (availableItems.Count == 0) return currentSelection;
+
+            List<ItemData> pool = new List<ItemData>(availableItems);
+            for (int i = 0; i < count && pool.Count > 0; i++)
+            {
+                int randomIndex = Random.Range(0, pool.Count);
+                currentSelection.Add(pool[randomIndex]);
+                pool.RemoveAt(randomIndex);
+            }
+
+            return currentSelection;
+        }
+
+        public void SelectItem(ItemData selectedItem)
+        {
+            if (selectedItem == null || playerController == null) return;
+
+            selectedItem.ApplyItemEffects(playerController.gameObject);
+        }
+    }
+}

